import { Session } from "node:inspector";
import { promisify } from "node:util";
import { foldProfile } from "./fold-profile.util.js";
/**
 * Samples per second.
 *
 * 99 rather than 100 so the sampler does not fall into lockstep with the 10ms
 * timers that `setInterval` and friends land on, systematically over- or
 * under-counting whatever runs on them.
 */
export const DEFAULT_SAMPLE_RATE_HZ = 99;
/** How much wall clock one upload window covers. */
export const DEFAULT_WINDOW_MS = 60_000;
/**
 * How much of each window is actually sampled.
 *
 * Duty cycling is what keeps continuous profiling affordable: the sampler runs
 * for this long, then stops until the next window. Ten seconds in sixty is a
 * sixth of the overhead, and a flame graph aggregated over minutes is no less
 * useful for it - the API stores the rate per window and reports coverage per
 * window, so a sparsely sampled window is a first-class answer rather than a
 * gap the client has to reason about.
 */
export const DEFAULT_DUTY_MS = 10_000;
/**
 * Share of one CPU the profiler may cost before it stops sampling.
 *
 * Measured across the sampling burst rather than the whole window, because
 * that is when the cost is incurred. Exceeding it disables profiling for the
 * process rather than degrading it quietly: an agent that silently eats a
 * tenth of a customer's CPU is worse than one that says it gave up.
 */
export const DEFAULT_MAX_CPU_PERCENT = 3;
/**
 * A wall-clock sampling profiler built on `node:inspector`.
 *
 * Deliberately not a native addon. V8's sampling profiler is already reachable
 * from the standard library through the inspector protocol, and a native
 * dependency would land in the install of every service that uses this agent -
 * including the overwhelming majority that will never switch profiling on.
 * Prebuilt binaries, unusual platforms, bundlers and Docker bases are a
 * permanent tax; the inspector session is none of those.
 *
 * The trade this makes is that samples arrive as a batch with timestamps rather
 * than carrying labels, so span attribution is a join done afterwards - see
 * `SpanSliceRecorder` for why that is sound on a single-threaded runtime.
 *
 * Sampling runs on the profiled thread by definition: V8 profiles the isolate
 * the session is attached to, so this cannot be moved onto the agent's worker.
 * Only the folding and upload are off the hot path.
 */
export class CpuProfilerService {
    slices;
    options;
    session = null;
    windowTimer = null;
    dutyTimer = null;
    running = false;
    disabled = false;
    sampleRateHz;
    windowMs;
    dutyMs;
    maxCpuPercent;
    constructor(slices, options) {
        this.slices = slices;
        this.options = options;
        this.sampleRateHz = options.sampleRateHz ?? DEFAULT_SAMPLE_RATE_HZ;
        this.windowMs = options.windowMs ?? DEFAULT_WINDOW_MS;
        // Clamped: a duty longer than the window would start the next burst before
        // the last one finished, and the two sessions would fight over the isolate.
        this.dutyMs = Math.min(options.dutyMs ?? DEFAULT_DUTY_MS, this.windowMs);
        this.maxCpuPercent = options.maxCpuPercent ?? DEFAULT_MAX_CPU_PERCENT;
    }
    /**
     * Begins duty-cycled profiling, resolving once the first burst is actually
     * sampling. Safe to call twice.
     *
     * Awaitable because starting is not instantaneous: the inspector handshake -
     * enable, set the interval, start - is several round trips through the
     * session's message loop, and until they complete nothing is being sampled.
     * A caller that fires this and immediately does work would profile none of
     * it, and a fire-and-forget signature gives them no way to find out.
     */
    async start() {
        if (this.windowTimer || this.disabled) {
            return;
        }
        // Unref'd so profiling never holds the process open. An agent that keeps a
        // CLI alive for a minute after its work is done is a bug report.
        this.windowTimer = setInterval(() => {
            void this.runWindow();
        }, this.windowMs);
        this.windowTimer.unref?.();
        await this.runWindow();
    }
    async stop() {
        if (this.windowTimer) {
            clearInterval(this.windowTimer);
            this.windowTimer = null;
        }
        if (this.dutyTimer) {
            clearTimeout(this.dutyTimer);
            this.dutyTimer = null;
        }
        if (this.running) {
            // Collect what the burst has so far rather than discarding it: shutdown
            // is exactly when the last window is most likely to explain something.
            await this.finish().catch(() => undefined);
        }
        this.closeSession();
        this.slices.reset();
    }
    /** Whether the profiler has given up on itself; see `maxCpuPercent`. */
    isDisabled() {
        return this.disabled;
    }
    async runWindow() {
        if (this.running || this.disabled) {
            return;
        }
        try {
            await this.beginBurst();
        }
        catch (err) {
            this.disable(`failed to start the profiler: ${String(err)}`);
            return;
        }
        this.dutyTimer = setTimeout(() => {
            void this.finish().catch((err) => this.disable(`failed to collect a profile: ${String(err)}`));
        }, this.dutyMs);
        this.dutyTimer.unref?.();
    }
    windowStartedAt = 0;
    windowStartedAtWallClock = 0;
    cpuAtStart = null;
    async beginBurst() {
        this.session = new Session();
        this.session.connect();
        const post = this.postTo(this.session);
        await post("Profiler.enable");
        await post("Profiler.setSamplingInterval", {
            // Microseconds between samples, which is how V8 expresses the rate.
            interval: Math.round(1_000_000 / this.sampleRateHz),
        });
        this.windowStartedAt = performance.now();
        this.windowStartedAtWallClock = Date.now();
        this.cpuAtStart = process.cpuUsage();
        this.running = true;
        await post("Profiler.start");
    }
    async finish() {
        if (!this.session || !this.running) {
            return;
        }
        const post = this.postTo(this.session);
        const { profile } = (await post("Profiler.stop"));
        this.running = false;
        const burstMs = performance.now() - this.windowStartedAt;
        const stacks = foldProfile(profile, {
            startedAt: this.windowStartedAt,
            slices: this.slices.drain(),
        });
        this.closeSession();
        if (stacks.length > 0) {
            this.options.onWindow({
                // The window the samples belong to, not the moment the burst ended -
                // coverage is expressed in windows and the backend keys rows on this.
                start: new Date(this.windowStartedAtWallClock).toISOString(),
                stacks,
            }, this.sampleRateHz);
        }
        this.enforceBudget(burstMs);
    }
    /**
     * Stops profiling for good if the burst cost more CPU than the budget.
     *
     * `process.cpuUsage` covers the whole process, so this measures the profiler
     * plus everything the application did during the burst - it cannot isolate
     * the sampler's own cost from JS. What it can do is catch the case that
     * matters: a process whose CPU is pinned while profiling is on. The threshold
     * is therefore applied to the increase over the burst rather than treated as
     * a precise attribution.
     */
    enforceBudget(burstMs) {
        if (!this.cpuAtStart || burstMs <= 0) {
            return;
        }
        const used = process.cpuUsage(this.cpuAtStart);
        const usedMs = (used.user + used.system) / 1000;
        const percent = (usedMs / burstMs) * 100;
        // Compared against a whole core's worth on top of the budget: anything less
        // is ordinary application load, which this cannot separate from the
        // profiler and must not blame it for.
        if (percent > 100 + this.maxCpuPercent) {
            this.disable(`CPU use during the sampling burst was ${percent.toFixed(1)}% of one core`);
        }
    }
    disable(reason) {
        this.disabled = true;
        this.running = false;
        if (this.windowTimer) {
            clearInterval(this.windowTimer);
            this.windowTimer = null;
        }
        if (this.dutyTimer) {
            clearTimeout(this.dutyTimer);
            this.dutyTimer = null;
        }
        this.closeSession();
        this.options.onDisabled?.(reason);
    }
    closeSession() {
        try {
            this.session?.disconnect();
        }
        catch {
            // Disconnecting an already-dead session is not worth surfacing.
        }
        this.session = null;
    }
    postTo(session) {
        // `Session.post` is callback-style with an optional params argument, and
        // its overloads do not survive promisify's typing.
        return promisify(session.post).bind(session);
    }
}
